package cn.flower.mall;

import com.fasterxml.jackson.databind.ObjectMapper;
import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import static cn.flower.mall.Store.m;

@Service
public class MallService {
 final Store db; final Tokens tokens; final ObjectMapper json;
 final BCryptPasswordEncoder encoder=new BCryptPasswordEncoder();
 private final Map<String,long[]> loginAttempts=new ConcurrentHashMap<>();
 public MallService(Store db,Tokens tokens,ObjectMapper json){this.db=db;this.tokens=tokens;this.json=json;}
 static void check(boolean ok,String msg){if(!ok)throw new BusinessException(msg);}
 static long id(Object x){try{return Long.parseLong(String.valueOf(x));}catch(Exception e){throw new BusinessException("编号格式错误");}}
 static int num(Object x){try{return Integer.parseInt(String.valueOf(x));}catch(Exception e){throw new BusinessException("数量格式错误");}}
 static String text(Map<String,Object>b,String key,int max,boolean required){String v=Objects.toString(b.get(key),"").trim();check(v.length()<=max&&(!required||!v.isBlank()),key+" 内容为空或超出长度限制");return v;}
 static BigDecimal money(Object x){try{var v=new BigDecimal(String.valueOf(x));check(v.scale()<=2&&v.signum()>0&&v.compareTo(new BigDecimal("99999999"))<0,"金额必须大于0且最多两位小数");return v.setScale(2);}catch(NumberFormatException e){throw new BusinessException("金额格式错误");}}
 Map<String,Object> must(String sql,Map<String,Object>p){var r=db.one(sql,p);if(r==null)throw new BusinessException(404,"记录不存在");return r;}
 String number(String prefix){return prefix+UUID.randomUUID().toString().replace("-","");}
 Map<String,Object> safeUser(Map<String,Object> u){var v=new LinkedHashMap<>(u);v.remove("password_hash");v.remove("token_version");return v;}
 @Transactional public Map<String,Object> register(Map<String,Object>b){String name=text(b,"username",40,true);check(name.matches("[A-Za-z0-9_]{4,40}"),"账号需为4至40位字母、数字或下划线");String pass=text(b,"password",72,true);check(pass.length()>=8,"密码至少8位");long uid=db.add("account",m("username",name,"password_hash",encoder.encode(pass),"nickname",text(b,"nickname",60,false).isBlank()?name:b.get("nickname"),"role","USER"));return m("id",uid);}
 public Map<String,Object> login(Map<String,Object>b,String role,String ip){
   String name=text(b,"username",40,true),pass=text(b,"password",72,true);long now=System.currentTimeMillis();String key=ip+":"+name;
   if(loginAttempts.size()>10000)loginAttempts.entrySet().removeIf(e->now-e.getValue()[0]>600000);
   var bucket=loginAttempts.compute(key,(k,v)->v==null||now-v[0]>600000?new long[]{now,1}:new long[]{v[0],v[1]+1});
   if(bucket[1]>20)throw new BusinessException(429,"登录尝试过于频繁，请10分钟后重试");
   var u=db.one("SELECT * FROM account WHERE username=#{p.name} AND role=#{p.role}",m("name",name,"role",role));
   check(u!=null&&encoder.matches(pass,(String)u.get("password_hash")),"账号或密码错误");check(num(u.get("status"))==1,"账号已被禁用");loginAttempts.remove(key);
   return m("token",tokens.create(u),"user",safeUser(u));
 }
 public Map<String,Object> user(long uid){return safeUser(must("SELECT * FROM account WHERE id=#{p.id}",m("id",uid)));}
 @Transactional public Object profile(long uid,Map<String,Object>b){String phone=text(b,"phone",20,false);check(phone.isBlank()||phone.matches("1[3-9]\\d{9}"),"请输入有效手机号");var v=m("nickname",text(b,"nickname",60,true),"phone",phone);String avatar=text(b,"avatar",500,false);if(!avatar.isBlank()){ownImage(uid,avatar,"avatar");v.put("avatar",avatar);}db.update("account",uid,v);return user(uid);}
 @Transactional public void password(long uid,Map<String,Object>b){var u=must("SELECT * FROM account WHERE id=#{p.id} FOR UPDATE",m("id",uid));check(encoder.matches(text(b,"old_password",72,true),(String)u.get("password_hash")),"原密码不正确");String pass=text(b,"password",72,true);check(pass.length()>=8,"密码至少8位");db.update("account",uid,m("password_hash",encoder.encode(pass),"token_version",num(u.get("token_version"))+1));}
 public Map<String,Object> page(String from,String columns,String where,Map<String,Object>p,int page,int size,String order){page=Math.max(1,page);size=Math.min(50,Math.max(1,size));p=new HashMap<>(p);p.put("limit",size);p.put("offset",(page-1)*size);var count=db.one("SELECT COUNT(*) AS total FROM "+from+" WHERE "+where,p);return m("items",db.list("SELECT "+columns+" FROM "+from+" WHERE "+where+" ORDER BY "+order+" LIMIT #{p.limit} OFFSET #{p.offset}",p),"total",count.get("total"),"page",page,"size",size);}
 public Map<String,Object> products(boolean admin,String q,long category,int page,int size){return page("product p LEFT JOIN category c ON c.id=p.category_id","p.*,c.name AS category_name,(SELECT COALESCE(AVG(r.rating),0) FROM review r WHERE r.product_id=p.id AND r.status=1 AND r.deleted=0) AS rating,(SELECT COUNT(*) FROM review r WHERE r.product_id=p.id AND r.status=1 AND r.deleted=0) AS review_count","p.deleted=0"+(admin?"":" AND p.status=1")+" AND (#{p.cat}=0 OR p.category_id=#{p.cat}) AND p.name LIKE #{p.q}",m("q","%"+q+"%","cat",category),page,size,"p.id DESC");}
 public Map<String,Object> product(long pid,boolean admin){var p=must("SELECT * FROM product WHERE id=#{p.id} AND deleted=0"+(admin?"":" AND status=1"),m("id",pid));p.put("images",db.list("SELECT * FROM product_image WHERE product_id=#{p.id} ORDER BY sort,id",m("id",pid)));p.put("rating",db.one("SELECT COALESCE(AVG(rating),0) AS rating,COUNT(*) AS review_count FROM review WHERE product_id=#{p.id} AND status=1 AND deleted=0",m("id",pid)));return p;}
 public Object flowers(String q){return db.list("SELECT * FROM flower_language WHERE name LIKE #{p.q} ORDER BY id",m("q","%"+q+"%"));}
 public Object flower(long fid){var f=must("SELECT * FROM flower_language WHERE id=#{p.id}",m("id",fid));f.put("products",db.list("SELECT p.* FROM product p JOIN product_flower_language f ON f.product_id=p.id WHERE f.flower_id=#{p.id} AND p.status=1 AND p.deleted=0",m("id",fid)));return f;}
 @Transactional public Object saveProduct(long admin,Long pid,Map<String,Object>b){
   if(pid!=null)product(pid,true);long cat=id(b.get("category_id"));must("SELECT * FROM category WHERE id=#{p.id}",m("id",cat));
   String cover=text(b,"cover",500,true);imageAllowed(admin,cover,"product");
   int warn=num(b.getOrDefault("warning_stock",10));check(warn>=0&&warn<=1000000,"库存预警值无效");int status=num(b.getOrDefault("status",1));check(status==0||status==1,"上架状态无效");
   var row=m("category_id",cat,"name",text(b,"name",100,true),"price",money(b.get("price")),"description",text(b,"description",6000,false),"specification",text(b,"specification",200,true),"cover",cover,"warning_stock",warn,"status",status);
   List<?> images=b.get("images") instanceof List<?> l?l:List.of();check(images.size()<=9,"详情图片最多9张");for(Object s:images)imageAllowed(admin,String.valueOf(s),"product");
   if(pid==null){int stock=num(b.getOrDefault("stock",0));check(stock>=0&&stock<=1000000,"初始库存无效");row.put("stock",stock);pid=db.add("product",row);if(stock>0)stockLog(pid,"入库",stock,0,stock,"商品初始库存",admin);}else db.update("product",pid,row);
   db.exec("DELETE FROM product_image WHERE product_id=#{p.id}",m("id",pid));db.add("product_image",m("product_id",pid,"image_url",cover,"image_type","cover","sort",0));int i=0;for(Object s:images)db.add("product_image",m("product_id",pid,"image_url",s,"image_type","detail","sort",++i));
   audit(admin,"商品保存",pid,"保存商品信息");return product(pid,true);
 }
 @Transactional public void productStatus(long admin,long pid,int status){check(status==0||status==1,"状态无效");product(pid,true);db.update("product",pid,m("status",status));audit(admin,"商品上下架",pid,"状态="+status);}
 @Transactional public void deleteProduct(long admin,long pid){product(pid,true);db.update("product",pid,m("deleted",1,"status",0));audit(admin,"商品逻辑删除",pid,"保留历史订单及图片");}
 void stockLog(long pid,String type,int change,int before,int after,String remark,long uid){db.add("stock_record",m("product_id",pid,"change_type",type,"change_quantity",change,"before_stock",before,"after_stock",after,"remark",remark,"operator_id",uid));}
 @Transactional public void stock(long uid,Map<String,Object>b,String type){long pid=id(b.get("product_id"));var p=must("SELECT * FROM product WHERE id=#{p.id} AND deleted=0 FOR UPDATE",m("id",pid));int before=num(p.get("stock")),qty=num(b.get("quantity"));check(qty>=0&&qty<=1000000,"库存数量无效");int after=switch(type){case "add"->before+qty;case "reduce"->before-qty;default->qty;};check(after>=0&&after<=1000000,"可售库存不足或超出上限");db.update("product",pid,m("stock",after));stockLog(pid,type.equals("add")?"入库":type.equals("reduce")?"出库":"其他调整",after-before,before,after,text(b,"remark",255,true),uid);}
 public Object stockList(String q,boolean warning,int page,int size){return page("product","*","deleted=0 AND name LIKE #{p.q}"+(warning?" AND stock<=warning_stock":""),m("q","%"+q+"%"),page,size,"stock ASC,id DESC");}
 public Object stockRecords(int page,int size){return page("stock_record s LEFT JOIN product p ON p.id=s.product_id","s.*,p.name","1=1",m(),page,size,"s.id DESC");}
 public Object cart(long uid){return db.list("SELECT c.id,c.quantity,p.id AS product_id,p.name,p.price,p.cover,p.specification,p.stock,p.status,p.deleted FROM cart c JOIN product p ON p.id=c.product_id WHERE c.user_id=#{p.uid} ORDER BY c.id DESC",m("uid",uid));}
 @Transactional public void addCart(long uid,Map<String,Object>b){long pid=id(b.get("product_id"));int qty=num(b.get("quantity"));check(qty>0&&qty<=999,"数量应为1至999");var p=product(pid,false);var c=db.one("SELECT * FROM cart WHERE user_id=#{p.uid} AND product_id=#{p.pid}",m("uid",uid,"pid",pid));int total=qty+(c==null?0:num(c.get("quantity")));check(total<=num(p.get("stock")),"商品库存不足");if(c==null)db.add("cart",m("user_id",uid,"product_id",pid,"quantity",qty));else db.update("cart",id(c.get("id")),m("quantity",total));}
 @Transactional public void updateCart(long uid,Map<String,Object>b){long cid=id(b.get("id"));var c=must("SELECT * FROM cart WHERE id=#{p.id} AND user_id=#{p.uid}",m("id",cid,"uid",uid));int qty=num(b.get("quantity"));var p=product(id(c.get("product_id")),false);check(qty>0&&qty<=999&&qty<=num(p.get("stock")),"数量无效或库存不足");db.update("cart",cid,m("quantity",qty));}
 @Transactional public void removeCart(long uid,long cid){db.exec("DELETE FROM cart WHERE id=#{p.id} AND user_id=#{p.uid}",m("id",cid,"uid",uid));}
 public Object addresses(long uid){return db.list("SELECT * FROM address WHERE user_id=#{p.uid} ORDER BY is_default DESC,id DESC",m("uid",uid));}
 @Transactional public Object saveAddress(long uid,Map<String,Object>b){db.one("SELECT id FROM account WHERE id=#{p.uid} FOR UPDATE",m("uid",uid));Long aid=b.get("id")==null?null:id(b.get("id"));if(aid!=null)must("SELECT * FROM address WHERE id=#{p.id} AND user_id=#{p.uid}",m("id",aid,"uid",uid));check(((List<?>)addresses(uid)).size()<50||aid!=null,"地址最多50条");String phone=text(b,"phone",20,true);check(phone.matches("1[3-9]\\d{9}"),"请输入有效手机号");int def=num(b.getOrDefault("is_default",0));check(def==0||def==1,"默认地址参数无效");if(def==1)db.exec("UPDATE address SET is_default=0 WHERE user_id=#{p.uid}",m("uid",uid));var row=m("user_id",uid,"receiver",text(b,"receiver",50,true),"phone",phone,"province",text(b,"province",50,true),"city",text(b,"city",50,true),"district",text(b,"district",50,true),"detail",text(b,"detail",200,true),"is_default",def);if(aid==null)db.add("address",row);else db.update("address",aid,row);return addresses(uid);}
 @Transactional public void deleteAddress(long uid,long aid){db.exec("DELETE FROM address WHERE id=#{p.id} AND user_id=#{p.uid}",m("id",aid,"uid",uid));}
 public Object favorites(long uid){return db.list("SELECT p.* FROM favorite f JOIN product p ON p.id=f.product_id WHERE f.user_id=#{p.uid} AND p.deleted=0 ORDER BY f.id DESC",m("uid",uid));}
 @Transactional public void favorite(long uid,long pid){product(pid,false);var f=db.one("SELECT * FROM favorite WHERE user_id=#{p.uid} AND product_id=#{p.pid}",m("uid",uid,"pid",pid));if(f==null)db.add("favorite",m("user_id",uid,"product_id",pid));else db.exec("DELETE FROM favorite WHERE id=#{p.id}",m("id",f.get("id")));}
 Map<String,Object> lockOrder(long oid,Long uid){var o=must("SELECT * FROM shop_order WHERE id=#{p.id} FOR UPDATE",m("id",oid));if(uid!=null&&id(o.get("user_id"))!=uid)throw new BusinessException(403,"无权访问此订单");return o;}
 public Map<String,Object> order(long oid,Long uid){var o=must("SELECT * FROM shop_order WHERE id=#{p.id}",m("id",oid));if(uid!=null&&id(o.get("user_id"))!=uid)throw new BusinessException(403,"无权访问此订单");o.put("items",db.list("SELECT i.*,(SELECT COUNT(*) FROM review r WHERE r.order_item_id=i.id) AS reviewed FROM order_item i WHERE i.order_id=#{p.id}",m("id",oid)));o.put("refunds",db.list("SELECT * FROM refund_record WHERE order_id=#{p.id} ORDER BY id DESC",m("id",oid)));return o;}
 public Object orders(Long uid,String q,int status,int page,int size){return page("shop_order o JOIN account u ON u.id=o.user_id","o.*,u.nickname","(#{p.uid}=0 OR o.user_id=#{p.uid}) AND o.order_no LIKE #{p.q} AND (#{p.s}=-1 OR o.status=#{p.s})",m("uid",uid==null?0:uid,"q","%"+q+"%","s",status),page,size,"o.id DESC");}
 @Transactional public Object createOrder(long uid,Map<String,Object>b){
   // Serialize a user's submissions, including duplicate idempotency keys.
   db.one("SELECT id FROM account WHERE id=#{p.uid} FOR UPDATE",m("uid",uid));String key=text(b,"request_key",100,true);
   var existing=db.one("SELECT id FROM shop_order WHERE user_id=#{p.uid} AND request_key=#{p.k}",m("uid",uid,"k",key));if(existing!=null)return order(id(existing.get("id")),uid);
   var address=must("SELECT * FROM address WHERE id=#{p.id} AND user_id=#{p.uid}",m("id",id(b.get("address_id")),"uid",uid));
   check(b.get("items") instanceof List<?>,"请选择商品");List<?> requested=(List<?>)b.get("items");check(!requested.isEmpty()&&requested.size()<=30,"商品数量需为1至30种");
   var quantities=new TreeMap<Long,Integer>();for(Object x:requested){check(x instanceof Map<?,?>,"商品参数无效");Map<?,?> item=(Map<?,?>)x;long pid=id(item.get("product_id"));int qty=num(item.get("quantity"));check(qty>0&&qty<=999,"购买数量无效");quantities.merge(pid,qty,Integer::sum);}
   var snapshots=new ArrayList<Map<String,Object>>();BigDecimal total=BigDecimal.ZERO;
   for(var e:quantities.entrySet()){var p=must("SELECT * FROM product WHERE id=#{p.id} FOR UPDATE",m("id",e.getKey()));check(num(p.get("status"))==1&&num(p.get("deleted"))==0,"商品已下架");int before=num(p.get("stock"));check(before>=e.getValue(),"商品库存不足："+p.get("name"));int changed=db.exec("UPDATE product SET stock=stock-#{p.qty} WHERE id=#{p.id} AND stock>=#{p.qty} AND status=1 AND deleted=0",m("id",e.getKey(),"qty",e.getValue()));check(changed==1,"库存不足");stockLog(e.getKey(),"订单预留",-e.getValue(),before,before-e.getValue(),"下单即从可售库存扣减",uid);var snap=m("product_id",e.getKey(),"name",p.get("name"),"cover",p.get("cover"),"specification",p.get("specification"),"price",p.get("price"),"quantity",e.getValue());snapshots.add(snap);total=total.add(new BigDecimal(p.get("price").toString()).multiply(BigDecimal.valueOf(e.getValue())));}
   check(total.compareTo(new BigDecimal("99999999"))<0,"订单金额超出上限");String snap;try{snap=json.writeValueAsString(address);}catch(Exception e){throw new IllegalStateException(e);}
   long oid=db.add("shop_order",m("order_no",number("FL"),"user_id",uid,"request_key",key,"total",total,"address_snapshot",snap,"greeting",text(b,"greeting",1000,false),"remark",text(b,"remark",500,false)));
   for(var item:snapshots){item.put("order_id",oid);db.add("order_item",item);db.exec("DELETE FROM cart WHERE user_id=#{p.uid} AND product_id=#{p.pid}",m("uid",uid,"pid",item.get("product_id")));}return order(oid,uid);
 }
 @Transactional public Object pay(long uid,long oid,boolean success){var o=lockOrder(oid,uid);if(num(o.get("payment_status"))==1)return order(oid,uid);check(num(o.get("status"))==0,"当前订单不能支付");
   if(!success)return m("success",false,"message","模拟支付失败，订单仍待支付");
   // No client amount or client payment state is trusted. This endpoint is deliberately MOCK only.
   db.add("payment_record",m("order_id",oid,"payment_no",number("MP"),"payment_amount",o.get("total"),"payment_status",1,"transaction_no",number("MT"),"pay_time",LocalDateTime.now()));db.update("shop_order",oid,m("status",1,"payment_status",1,"pay_time",LocalDateTime.now()));return order(oid,uid);
 }
 void restoreStock(Map<String,Object>o,long operator){if(num(o.get("stock_restored"))==1)return;var items=db.list("SELECT * FROM order_item WHERE order_id=#{p.id} ORDER BY product_id",m("id",o.get("id")));for(var item:items){long pid=id(item.get("product_id"));var p=must("SELECT * FROM product WHERE id=#{p.id} FOR UPDATE",m("id",pid));int before=num(p.get("stock")),qty=num(item.get("quantity"));db.exec("UPDATE product SET stock=stock+#{p.qty} WHERE id=#{p.id}",m("qty",qty,"id",pid));stockLog(pid,"取消恢复",qty,before,before+qty,"订单取消/制作前全额退款",operator);}db.update("shop_order",id(o.get("id")),m("stock_restored",1));}
 @Transactional public void cancel(long uid,long oid){var o=lockOrder(oid,uid);check(num(o.get("status"))==0,"只有待支付订单可直接取消，已支付请申请退款");restoreStock(o,uid);db.update("shop_order",oid,m("status",6));}
 boolean pending(long oid){return id(db.one("SELECT COUNT(*) AS n FROM refund_record WHERE order_id=#{p.id} AND refund_status IN (1,2,5)",m("id",oid)).get("n"))>0;}
 @Transactional public void orderAction(long admin,long oid,String action,Map<String,Object>b){var o=lockOrder(oid,null);int s=num(o.get("status"));check(num(o.get("payment_status"))==1,"未支付订单不能处理");check(!pending(oid),"订单存在待处理退款，请先处理退款");
   if(action.equals("reject")){check(s==1,"仅待接单订单可拒单");String reason=text(b,"reason",500,true);db.update("shop_order",oid,m("status",7,"reject_reason",reason));BigDecimal left=new BigDecimal(o.get("total").toString()).subtract(new BigDecimal(o.get("refunded").toString()));if(left.signum()>0)db.add("refund_record",m("refund_no",number("RF"),"order_id",oid,"user_id",o.get("user_id"),"refund_amount",left,"refund_reason","商家拒单","refund_remark",reason,"refund_status",2,"audit_time",LocalDateTime.now(),"auto_cancel",1));
   }else {int next=action.equals("accept")?2:num(b.get("status"));check((s==1&&next==2)||(s==2&&next==3)||(s==3&&next==4)||(s==4&&next==5),"订单状态不能跳跃或回退");db.update("shop_order",oid,m("status",next));}audit(admin,"订单处理",oid,action);
 }
 @Transactional public Object applyRefund(long uid,Map<String,Object>b){long oid=id(b.get("order_id"));var o=lockOrder(oid,uid);check(num(o.get("payment_status"))==1&&!Set.of(6,7).contains(num(o.get("status"))),"订单不符合退款条件");check(!pending(oid),"此订单已有待处理退款");BigDecimal amount=money(b.get("amount")),left=new BigDecimal(o.get("total").toString()).subtract(new BigDecimal(o.get("refunded").toString()));check(amount.compareTo(left)<=0,"退款金额超过尚可退金额");long rid=db.add("refund_record",m("refund_no",number("RF"),"order_id",oid,"user_id",uid,"refund_amount",amount,"refund_reason",text(b,"reason",255,true),"refund_remark",text(b,"remark",500,false)));return refund(rid,uid);}
 public Object refund(long rid,Long uid){var r=must("SELECT r.*,o.order_no FROM refund_record r JOIN shop_order o ON o.id=r.order_id WHERE r.id=#{p.id}",m("id",rid));if(uid!=null&&id(r.get("user_id"))!=uid)throw new BusinessException(403,"无权访问此退款");return r;}
 public Object refunds(Long uid,int page,int size){return page("refund_record r JOIN shop_order o ON o.id=r.order_id","r.*,o.order_no","(#{p.uid}=0 OR r.user_id=#{p.uid})",m("uid",uid==null?0:uid),page,size,"r.id DESC");}
 @Transactional public void auditRefund(long admin,long rid,boolean approved,Map<String,Object>b){var initial=must("SELECT * FROM refund_record WHERE id=#{p.id}",m("id",rid));lockOrder(id(initial.get("order_id")),null);var r=must("SELECT * FROM refund_record WHERE id=#{p.id} FOR UPDATE",m("id",rid));int s=num(r.get("refund_status"));check(s==1||s==5,"退款不能重复审核");check(approved||num(r.get("auto_cancel"))==0,"商家拒单退款不能拒绝，请重试退款");db.update("refund_record",rid,m("refund_status",approved?2:4,"audit_time",LocalDateTime.now(),"reject_reason",approved?"":text(b,"reason",500,true),"fail_reason",""));audit(admin,approved?"退款同意":"退款拒绝",rid,approved?"等待后端模拟退款":text(b,"reason",500,true));}
 @Transactional public void processRefund(long rid,boolean fail){var first=must("SELECT * FROM refund_record WHERE id=#{p.id}",m("id",rid));var o=lockOrder(id(first.get("order_id")),null);var r=must("SELECT * FROM refund_record WHERE id=#{p.id} FOR UPDATE",m("id",rid));if(num(r.get("refund_status"))!=2)return;if(fail){db.update("refund_record",rid,m("refund_status",5,"fail_reason","测试开关触发模拟渠道失败，可由商家重试"));return;}
   BigDecimal refunded=new BigDecimal(o.get("refunded").toString()).add(new BigDecimal(r.get("refund_amount").toString()));check(refunded.compareTo(new BigDecimal(o.get("total").toString()))<=0,"退款金额超过支付金额");boolean full=refunded.compareTo(new BigDecimal(o.get("total").toString()))==0;int state=num(o.get("status"));db.update("refund_record",rid,m("refund_status",3,"refund_time",LocalDateTime.now(),"transaction_refund_no",number("MR"),"fail_reason",""));db.update("shop_order",id(o.get("id")),m("refunded",refunded));
   if(full){if(state<=2||state==7)restoreStock(o,id(o.get("user_id")));db.update("shop_order",id(o.get("id")),m("status",state==7?7:6));}
 }
 void audit(long uid,String action,long target,String reason){db.add("audit_log",m("operator_id",uid,"action",action,"target_id",target,"reason",reason));}
 void ownImage(long uid,String url,String purpose){check(db.one("SELECT id FROM uploaded_file WHERE owner_id=#{p.uid} AND url=#{p.url} AND purpose=#{p.purpose}",m("uid",uid,"url",url,"purpose",purpose))!=null,"图片不存在、类型不匹配或不属于当前用户");}
 void imageAllowed(long uid,String url,String purpose){if(url.matches("/images/bouquet-[1-6]\\.svg"))return;ownImage(uid,url,purpose);}
 public Object reviews(Long uid,Long pid,boolean admin,int rating,int page,int size,String q){var result=page("review r JOIN account u ON u.id=r.user_id JOIN product p ON p.id=r.product_id JOIN order_item i ON i.id=r.order_item_id","r.*,u.nickname,u.avatar,p.name AS product_name,i.specification,(SELECT content FROM review_reply rr WHERE rr.review_id=r.id) AS reply","r.deleted=0"+(admin||uid!=null?"":" AND r.status=1")+" AND (#{p.uid}=0 OR r.user_id=#{p.uid}) AND (#{p.pid}=0 OR r.product_id=#{p.pid}) AND (#{p.rating}=0 OR r.rating=#{p.rating}) AND p.name LIKE #{p.q}",m("uid",uid==null?0:uid,"pid",pid==null?0:pid,"rating",rating,"q","%"+q+"%"),page,size,"r.id DESC");for(Object x:(List<?>)result.get("items")){var r=(Map<String,Object>)x;r.put("images",db.list("SELECT * FROM review_image WHERE review_id=#{p.id} ORDER BY sort,id",m("id",r.get("id"))));}if(admin)for(Object x:(List<?>)result.get("items")){var r=(Map<String,Object>)x;r.put("reports",db.list("SELECT reason,status,create_time FROM review_report WHERE review_id=#{p.id} ORDER BY id DESC",m("id",r.get("id"))));}return result;}
 @Transactional public Object saveReview(long uid,Long rid,Map<String,Object>b){Map<String,Object> old=null;long itemId;if(rid!=null){old=must("SELECT * FROM review WHERE id=#{p.id} AND user_id=#{p.uid} AND deleted=0 FOR UPDATE",m("id",rid,"uid",uid));itemId=id(old.get("order_item_id"));}else itemId=id(b.get("order_item_id"));
   var i=must("SELECT i.*,o.user_id,o.status FROM order_item i JOIN shop_order o ON o.id=i.order_id WHERE i.id=#{p.id}",m("id",itemId));check(id(i.get("user_id"))==uid&&num(i.get("status"))==5,"只能评价自己已完成订单的商品");int rating=num(b.get("rating"));check(rating>=1&&rating<=5,"评分应为1至5星");List<?> images=b.get("images") instanceof List<?> l?l:List.of();check(images.size()<=9,"评价图片最多9张");for(Object url:images)ownImage(uid,String.valueOf(url),"review");var row=m("user_id",uid,"product_id",i.get("product_id"),"order_id",i.get("order_id"),"order_item_id",itemId,"rating",rating,"content",text(b,"content",2000,true),"status",1,"update_time",LocalDateTime.now());if(rid==null)rid=db.add("review",row);else db.update("review",rid,row);db.exec("DELETE FROM review_image WHERE review_id=#{p.id}",m("id",rid));int n=0;for(Object url:images)db.add("review_image",m("review_id",rid,"image_url",url,"sort",n++));return m("id",rid);}
 @Transactional public void deleteReview(long uid,long rid){var r=must("SELECT * FROM review WHERE id=#{p.id} AND user_id=#{p.uid}",m("id",rid,"uid",uid));db.update("review",rid,m("deleted",1));}
 @Transactional public void reply(long admin,long rid,Map<String,Object>b){must("SELECT * FROM review WHERE id=#{p.id} AND deleted=0 FOR UPDATE",m("id",rid));var old=db.one("SELECT * FROM review_reply WHERE review_id=#{p.id}",m("id",rid));var row=m("review_id",rid,"admin_id",admin,"content",text(b,"content",1000,true));if(old==null)db.add("review_reply",row);else db.update("review_reply",id(old.get("id")),row);}
 @Transactional public void moderate(long admin,long rid,Map<String,Object>b){must("SELECT * FROM review WHERE id=#{p.id} AND deleted=0",m("id",rid));int status=num(b.get("status"));check(status==0||status==1,"状态无效");String reason=text(b,"reason",500,true);db.update("review",rid,m("status",status));db.exec("UPDATE review_report SET status=1 WHERE review_id=#{p.id}",m("id",rid));audit(admin,"评价审核",rid,reason);}
 public Object users(String q,int page,int size){return page("account u","u.id,u.username,u.nickname,u.phone,u.status,u.create_time,(SELECT COUNT(*) FROM shop_order o WHERE o.user_id=u.id) AS order_count,(SELECT COALESCE(SUM(o.total-o.refunded),0) FROM shop_order o WHERE o.user_id=u.id AND o.payment_status=1) AS consumption","u.role='USER' AND (u.nickname LIKE #{p.q} OR u.phone LIKE #{p.q} OR u.username LIKE #{p.q})",m("q","%"+q+"%"),page,size,"u.id DESC");}
 @Transactional public void userStatus(long admin,long uid,int status){check(status==0||status==1,"状态无效");var u=must("SELECT * FROM account WHERE id=#{p.id} AND role='USER' FOR UPDATE",m("id",uid));db.update("account",uid,m("status",status,"token_version",num(u.get("token_version"))+1));audit(admin,"用户状态",uid,"状态="+status);}
 public Object overview(){var pay=db.one("SELECT COALESCE(SUM(payment_amount),0) AS revenue,COALESCE(SUM(CASE WHEN pay_time>=#{p.today} THEN payment_amount ELSE 0 END),0) AS today_revenue,COALESCE(SUM(CASE WHEN pay_time>=#{p.month} THEN payment_amount ELSE 0 END),0) AS month_revenue FROM payment_record WHERE payment_status=1",m("today",java.time.LocalDate.now().atStartOfDay(),"month",java.time.LocalDate.now().withDayOfMonth(1).atStartOfDay()));var refund=db.one("SELECT COALESCE(SUM(refund_amount),0) AS refunded FROM refund_record WHERE refund_status=3",m());pay.putAll(refund);pay.put("net",new BigDecimal(pay.get("revenue").toString()).subtract(new BigDecimal(refund.get("refunded").toString())));pay.putAll(db.one("SELECT COUNT(*) AS orders,COALESCE(SUM(CASE WHEN status=1 THEN 1 ELSE 0 END),0) AS pending,COALESCE(SUM(CASE WHEN status=5 THEN 1 ELSE 0 END),0) AS completed,COALESCE(SUM(CASE WHEN create_time>=#{p.today} THEN 1 ELSE 0 END),0) AS today_orders,COALESCE(SUM(CASE WHEN create_time>=#{p.month} THEN 1 ELSE 0 END),0) AS month_orders FROM shop_order",m("today",java.time.LocalDate.now().atStartOfDay(),"month",java.time.LocalDate.now().withDayOfMonth(1).atStartOfDay())));pay.putAll(db.one("SELECT COUNT(*) AS low_stock,COALESCE(SUM(CASE WHEN stock=0 THEN 1 ELSE 0 END),0) AS sold_out FROM product WHERE deleted=0 AND stock<=warning_stock",m()));pay.put("pending_refunds",db.one("SELECT COUNT(*) AS n FROM refund_record WHERE refund_status=1",m()).get("n"));pay.putAll(db.one("SELECT COUNT(*) AS reviews,COALESCE(AVG(rating),0) AS rating FROM review WHERE deleted=0 AND status=1",m()));pay.put("ranking",db.list("SELECT i.product_id,i.name,SUM(i.quantity) AS quantity,SUM(i.quantity*i.price) AS amount FROM order_item i JOIN shop_order o ON o.id=i.order_id WHERE o.payment_status=1 GROUP BY i.product_id,i.name ORDER BY quantity DESC LIMIT 10",m()));return pay;}
 public Object revenue(String start,String end,int page,int size){var p=m("start",date(start,false),"end",date(end,true));var data=page("payment_record p JOIN shop_order o ON o.id=p.order_id","p.*,o.order_no,o.refunded,(p.payment_amount-o.refunded) AS net","p.payment_status=1 AND p.pay_time>=#{p.start} AND p.pay_time<#{p.end}",p,page,size,"p.id DESC");data.put("totals",db.one("SELECT (SELECT COALESCE(SUM(payment_amount),0) FROM payment_record WHERE payment_status=1 AND pay_time>=#{p.start} AND pay_time<#{p.end}) AS paid,(SELECT COALESCE(SUM(refund_amount),0) FROM refund_record WHERE refund_status=3 AND refund_time>=#{p.start} AND refund_time<#{p.end}) AS refunded",p));return data;}
 LocalDateTime date(String s,boolean end){try{return s.isBlank()?(end?java.time.LocalDate.now().plusDays(1).atStartOfDay():java.time.LocalDate.of(2000,1,1).atStartOfDay()):java.time.LocalDate.parse(s).plusDays(end?1:0).atStartOfDay();}catch(Exception e){throw new BusinessException("日期格式应为yyyy-MM-dd");}}
 public Object trend(){return db.list("SELECT CAST(pay_time AS DATE) AS `day`,SUM(payment_amount) AS amount,COUNT(*) AS count FROM payment_record WHERE payment_status=1 AND pay_time>=#{p.start} GROUP BY CAST(pay_time AS DATE) ORDER BY `day`",m("start",java.time.LocalDate.now().minusDays(29).atStartOfDay()));}
}


